class BattleRobot {
  constructor(name, health, position = { x: 0, y: 0 }) {
    this.name = name;
    this.health = health;
    this.position = position;
    this.gadgets = []; // This should be moved to a new class
  }

  takeDamage(amount) {
    this.health -= amount;
    console.log(`${this.name} took ${amount} damage. Health: ${this.health}`);
  }

  move(dx, dy) {
    this.position.x += dx;
    this.position.y += dy;
    console.log(`${this.name} moved to (${this.position.x}, ${this.position.y})`);
  }

  // TODO: Move these gadget-related methods and the 'gadgets' array
  // into a new 'RobotGadgetBay' class.
  // The BattleRobot should then contain an instance of RobotGadgetBay.
  addGadget(gadget) {
    this.gadgets.push(gadget);
    console.log(`${this.name} picked up ${gadget}. Gadgets: ${this.gadgets.join(', ')}`);
  }

  activateGadget(gadget) {
    const index = this.gadgets.indexOf(gadget);
    if (index > -1) {
      this.gadgets.splice(index, 1);
      console.log(`${this.name} activated ${gadget}. Gadgets left: ${this.gadgets.join(', ')}`);
      return true;
    }
    console.log(`${this.name} tried to activate ${gadget} but doesn't have it.`);
    return false;
  }
}

