class RobotGadgetBay {
  #gadgets;

  constructor() {
    this.#gadgets = [];
  }

  addGadget(gadget) {
    this.#gadgets.push(gadget);
    console.log(`Gadget Bay added ${gadget}. Current gadgets: ${this.#gadgets.join(', ')}`);
  }

  activateGadget(gadget) {
    const index = this.#gadgets.indexOf(gadget);
    if (index > -1) {
      this.#gadgets.splice(index, 1);
      console.log(`Gadget Bay activated ${gadget}. Gadgets left: ${this.#gadgets.join(', ')}`);
      return true;
    }
    console.log(`Gadget Bay doesn't contain ${gadget}.`);
    return false;
  }

  listGadgets() {
    return [...this.#gadgets];
  }
}

class BattleRobot {
  #gadgetBay;

  constructor(name, health, position = { x: 0, y: 0 }) {
    this.name = name;
    this.health = health;
    this.position = position;
    this.#gadgetBay = new RobotGadgetBay();
  }

  takeDamage(amount) {
    this.health -= amount;
    console.log(`${this.name} took ${amount} damage. Health: ${this.health}`);
  }

  move(dx, dy) {
    this.position.x += dx;
    this.position.y += dy;
    console.log(`${this.name} moved to (${this.position.x}, ${this.position.y})`);
  }

  addGadget(gadget) {
    this.#gadgetBay.addGadget(gadget);
  }

  activateGadget(gadget) {
    return this.#gadgetBay.activateGadget(gadget);
  }

  listEquippedGadgets() {
    return this.#gadgetBay.listGadgets();
  }
}

// Example Usage:
const bot = new BattleRobot('Sentinel-01', 100);
bot.takeDamage(10);
bot.move(5, 3);
bot.addGadget('Energy Shield');
bot.addGadget('Repair Kit');
bot.activateGadget('Energy Shield');
console.log(`Remaining gadgets for ${bot.name}: ${bot.listEquippedGadgets().join(', ')}`);

